from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
base='output/enterprise-modernization-assessment/'
s=getSampleStyleSheet();s.add(ParagraphStyle(name='T',parent=s['Title'],fontName='Helvetica-Bold',fontSize=22,leading=27,alignment=TA_CENTER,textColor=colors.HexColor('#102A43'),spaceAfter=8));s.add(ParagraphStyle(name='B',parent=s['BodyText'],fontSize=9.5,leading=13,textColor=colors.HexColor('#243B53'),spaceAfter=7));s.add(ParagraphStyle(name='H',parent=s['Heading1'],fontName='Helvetica-Bold',fontSize=15,leading=18,textColor=colors.HexColor('#102A43'),spaceBefore=9,spaceAfter=5));s.add(ParagraphStyle(name='C',parent=s['BodyText'],fontSize=9.5,leading=13,textColor=colors.HexColor('#102A43'),backColor=colors.HexColor('#EAF4FF'),borderColor=colors.HexColor('#9FB3C8'),borderWidth=.5,borderPadding=7,spaceAfter=8));s.add(ParagraphStyle(name='SM',parent=s['BodyText'],fontSize=7.5,leading=10,textColor=colors.HexColor('#243B53')))
def p(x,k='B'):return Paragraph(x,s[k])
def t(rows):
 x=Table([[p(q,'SM') for q in r] for r in rows],colWidths=[45*mm,72*mm,45*mm],repeatRows=1);x.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#243B53')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#BCCCDC')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F0F4F8')]),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]));return x
def make(file,title,lead,rows):
 d=SimpleDocTemplate(base+file,pagesize=A4,leftMargin=18*mm,rightMargin=18*mm,topMargin=16*mm,bottomMargin=18*mm);z=[Spacer(1,15*mm),p('License Manager','T'),p(title,'T'),p('Enterprise modernization assessment | 31 October 2026','B'),p(lead,'C'),p('Verified position','H'),p('Local authenticated screens and repository evidence were inspected read-only. Production remains unverified. Reconciliation figures are displayed metrics only: 1,043 BOEs, 317 invoices, 2 matches, 53 unmatched invoices and 1,699 duplicate-debit candidates.','B'),p('Scope and decision','H'),t(rows),p('Integrity statement','H'),p('No source code, business data, migration, configuration or production system was changed. Critical business outcomes require isolated test evidence and owner/domain approval before implementation.','C')];d.build(z)
make('LICENSE_MANAGER_ENTERPRISE_ASSESSMENT.pdf','Enterprise assessment','Trustworthiness of company isolation, balances, restrictions and reconciliation must precede visual redesign and new accounting.',[['Focus','Required outcome','Priority'],['Data/reconciliation','Reproduce/classify candidate metrics','P0'],['Company isolation','Tenant-scoped server data boundary','P0'],['Calculations','Canonical balance/restriction contract','P0'],['UX/testing','Actionable workflows and evidence gates','P1']])
make('LICENSE_MANAGER_OPTION_A_WITHOUT_ACCOUNTING.pdf','Option A - without accounting','Operational hardening: licence, DFIA/SION, BOE, invoices, reconciliation, data remediation, security and UX. Excludes a new GL/bank accounting system.',[['Phase','Deliverable','Likely days'],['Foundation','Evidence, isolation, tests','63'],['Correctness','Canonical calculations/restrictions','135'],['Operations','BOE/trade/reconciliation','95'],['UX/release','Reports, owner queue, recovery','152']])
make('LICENSE_MANAGER_OPTION_B_WITH_ACCOUNTING.pdf','Option B - with accounting','Option A plus chart, journals, subledgers, controlled source posting, bank reconciliation and CA-led migration.',[['Layer','Deliverable','Likely days'],['Foundation','Option A','445'],['Journals','Chart, period, balanced posting','120'],['Subledger/bank','AR/AP, payments, statements/matching','155'],['Cutover','Opening/migration/parallel reconcile','130']])
make('LICENSE_MANAGER_MASTER_IMPLEMENTATION_ROADMAP.pdf','Master implementation roadmap','A staged modular-monolith modernization designed for one developer and a small operations team.',[['Sequence','Exit gate','Risk reduced'],['0-1 Baseline/isolation','Reproducible tests and scoped access','Data leakage'],['2-3 Calculations/restrictions','Golden/concurrency parity','Overspend'],['4-5 Operations/remediation','Traceable corrections/queues','Bad data'],['6 Release/Option B','Recovery/UAT then accounting','Unsafe deployment']])
print('done')
